import json
import tempfile
import os
from langflow.custom import Component
from langflow.io import FileInput, MessageTextInput, Output
from langflow.schema.message import Message


class DeepgramDiarizadorComponent(Component):
    display_name = "Diarizador Deepgram"
    description = "Transcribe y diariza audio usando la API de Deepgram"
    icon = "microphone"

    inputs = [
        FileInput(
            name="archivo_audio",
            display_name="Archivo de Audio",
            info="Archivo MP3/MP4/WAV a transcribir",
            file_types=["mp3", "mp4", "wav", "m4a"],
        ),
        MessageTextInput(
            name="deepgram_api_key",
            display_name="Deepgram API Key",
            info="Tu API key de Deepgram",
        ),
    ]

    outputs = [
        Output(
            display_name="Texto Diarizado",
            name="texto_diarizado",
            method="transcribir",
        )
    ]

    def transcribir(self) -> Message:
        try:
            from deepgram import DeepgramClient, PrerecordedOptions

            client = DeepgramClient(self.deepgram_api_key)

            with open(self.archivo_audio, "rb") as f:
                audio_data = f.read()

            options = PrerecordedOptions(
                model="nova-2",
                language="es",
                diarize=True,
                punctuate=True,
                utterances=True,
            )

            response = client.listen.prerecorded.v("1").transcribe_file(
                {"buffer": audio_data},
                options
            )

            resultado = response.to_dict()
            utterances = resultado.get("results", {}).get("utterances", [])

            if not utterances:
                return Message(text="ERROR: No se detectaron intervenciones en el audio.")

            # Agrupar en turnos por hablante
            turnos = []
            turno_actual = None

            for utt in utterances:
                speaker = f"SPEAKER_{str(utt['speaker']).zfill(2)}"
                texto = utt["transcript"].strip()

                if turno_actual is None or turno_actual["speaker"] != speaker:
                    if turno_actual:
                        turnos.append(turno_actual)
                    turno_actual = {"speaker": speaker, "texto": texto}
                else:
                    turno_actual["texto"] += " " + texto

            if turno_actual:
                turnos.append(turno_actual)

            # Formato compatible con el resto del pipeline
            lineas = ["# 📝 Transcripción Cronológica (Diarización)\n"]
            for i, turno in enumerate(turnos, 1):
                lineas.append(f'*   **Turno {i} - {turno["speaker"]}:** "{turno["texto"]}"')

            return Message(text="\n".join(lineas))

        except Exception as e:
            import traceback
            return Message(text=f"ERROR: {str(e)}\n\n{traceback.format_exc()}")

import sys
import json
import re
from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message


class TRACEDebateComponent(Component):
    display_name = "TRACE Debate Scorer"
    description = "Evalúa la calidad argumentativa de cada hablante usando TRACE"
    icon = "chart-bar"

    inputs = [
        MessageTextInput(
            name="texto_diarizado",
            display_name="Texto Diarizado",
            info="Salida del diarizador con turnos por hablante",
        )
    ]

    outputs = [
        Output(
            display_name="TRACE JSON",
            name="trace_json",
            method="score_debate",
        )
    ]

    def score_debate(self) -> Message:
        texto = self.texto_diarizado
        if not texto or texto.strip() == "":
            return Message(text="{}")

        try:
            TRACE_PATH = '/root/juez-wsdc/trace-module/eval'
            MODEL_DIR = '/root/juez-wsdc/models/trace'

            if TRACE_PATH not in sys.path:
                sys.path.insert(0, TRACE_PATH)

            from transformers import AutoTokenizer, AutoConfig
            import torch
            import torch.nn as nn
            from safetensors.torch import load_file
            from transformers import AutoModel
            from calculate import binarize_predictions, calculate_trace_from_labels
            from parser import SentenceParser

            tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR, local_files_only=True)
            config = AutoConfig.from_pretrained(MODEL_DIR, local_files_only=True)

            class TraceDeBERTa(nn.Module):
                def __init__(self, config, num_labels=8):
                    super().__init__()
                    self.deberta = AutoModel.from_config(config)
                    self.classifier = nn.Linear(config.hidden_size, num_labels)

                def forward(self, input_ids, attention_mask=None):
                    outputs = self.deberta(input_ids=input_ids, attention_mask=attention_mask)
                    return torch.sigmoid(self.classifier(outputs.last_hidden_state[:, 0, :]))

            model = TraceDeBERTa(config)
            weights_path = f"{MODEL_DIR}/model.safetensors"
            state_dict = {k: v for k, v in load_file(weights_path).items() if not k.startswith("pooler.")}
            model.load_state_dict(state_dict, strict=False)
            model.eval()

            labels = ["Claim", "Data/Evidence", "Warrant", "Backing", "Qualifier", "Rebuttal", "Monitoring", "Evaluation"]

            turns = re.findall(r'SPEAKER_(\w+):\*\*\s*"(.*?)"', texto, re.DOTALL)

            por_hablante = {}
            for speaker, texto_turno in turns:
                key = f"SPEAKER_{speaker}"
                if key not in por_hablante:
                    por_hablante[key] = []
                por_hablante[key].append(texto_turno.strip())

            parser = SentenceParser()

            resultado = {}
            for speaker, turnos in por_hablante.items():
                texto_completo = " ".join(turnos)
                oraciones = parser.parse(texto_completo)
                if not oraciones:
                    resultado[speaker] = {"trace_score": 0.0, "num_sentences": 0, "label_counts": {}}
                    continue

                all_preds = []
                for oracion in oraciones:
                    enc = tokenizer(oracion, return_tensors="pt", truncation=True, max_length=512)
                    enc = {k: v for k, v in enc.items() if k in ['input_ids', 'attention_mask']}
                    with torch.no_grad():
                        preds = model(**enc)
                    all_preds.append({label: float(score) for label, score in zip(labels, preds[0])})

                binarios = [binarize_predictions(p) for p in all_preds]
                score = calculate_trace_from_labels(binarios)

                conteo = {}
                for b in binarios:
                    for label, val in b.items():
                        if val == 1:
                            conteo[label] = conteo.get(label, 0) + 1

                resultado[speaker] = {
                    "trace_score": round(score, 4),
                    "num_sentences": len(oraciones),
                    "label_counts": dict(sorted(conteo.items(), key=lambda x: x[1], reverse=True))
                }

            return Message(text=json.dumps(resultado, indent=2, ensure_ascii=False))

        except Exception as e:
            import traceback
            return Message(text=f"ERROR: {str(e)}\n\n{traceback.format_exc()}")
